import json
from pathlib import Path
S=Path(__file__).resolve().parents[1];cat=json.loads((S/'data/catalog.json').read_text(encoding='utf8'));p=S/'analysis/SuperDaily.json';out=json.loads(p.read_text(encoding='utf8')) if p.exists() else {}
base={'滑價xTick':'空白0，純數×商品最小升降單位，%按平倉價換點數；共用FIFO實現損益以平倉筆滑價扣兩側，不另外加本地手續費。','計算DD方式':'此策略未讀取此模式，也未呼叫日換；不會僅靠選每日DD就補每日市價估值。','KBAR間隔ex':'此版核心未呼叫ValidKBAR，不過濾每根；繼承欄位在此不生效。','開始交易時間':'此版核心未用此時間限制進出；商品資料載入的開始／最後時窗由商品設定控制。','最後交易時間':'此版未用此截止，不會到時自動平倉。','收盤交易時間':'此版未讀取此欄位；實際收盤判定或指定時刻依策略本身規則。','開始日期':'執行介面會填入目前回測起日；實際資料由載入起訖裁切，非本核心額外一套日內進場條件。','結束日期':'執行介面填目前回測結束日，載入資料先按此區間裁切；是否末端強平需看此策略實作。'}
cost='同一策略實例在本次回測內的所有子部位共用FIFO配對，不依子策略ID分帳，未平倉不估市價DD；多個子項或相反方向可能先互抵。滑價%以退出當筆價格算雙側，並非每側各以自己的成交價計。'
def add(name,summary,family,entry,exit,mechanics,caveats,notes={}):
 iid='SuperDaily/Stg'+name;nn=base|notes;out[iid]={'summary':summary,'family':family,'entry':entry,'exit':exit,'mechanics':mechanics,'caveats':caveats,'parameterNotes':{p['name']:nn[p['name']] for p in next(i for i in cat['items'] if i['id']==iid)['parameters']}}
for name in ['HDS','HD2']:
 hd2=name=='HD2';entry=['在相鄰資料跨曆日的前一日最後一分鐘，以期貨close對現貨日收盤：期貨<現貨做多一口，>=則做空一口。現貨查找找不到同日可退回之前最近可用日。','方向相同就續抱，反向時一筆兩口從+1轉−1或−1轉+1；只有一個策略項，不是每天新增一筆並行倉。']
 ex=['換倉事件先按當筆close退出舊部位，不直接開新合約。']
 ca=['訊號以曆日跨日判定，不是指定商品日盤收盤時間；含夜盤資料可在午夜換日觸發。','單腿交易期貨，只把現貨作方向訊號，不同時下現貨避險腿。']
 notes={}
 if hd2:
  summary='收盤比較期現價差決定一口方向，每天重設固定停損；可用本日收盤或下一日開盤作停損參考。'
  entry.append('每天即使同方向續抱，也依當日收盤或已知下一筆open重設停損；從次日開盤模式只改風控基準，真正進場仍是前日close。')
  ex+=['非日界資料以open觸固定停損就平倉，等下次日界訊號才再進；日界那根優先處理方向與重設，不先查原停損。','資料末筆一律close退出後continue，不再建立新訊號；換倉當根同樣退出後略過。']
  notes={'停損策略':'從收盤開始以本根close設停損；從次日開盤開始直接讀下一筆open作參考，但不改前日close入場價。','停損比':'持多參考價減%或點數、持空加，按最小升降單位Round；每天同方向也重設，不是單向推移。'}
  ca.append('從次日開盤模式在前一天建立停損時已讀下一筆open；日界不查舊停損，不能當成連續每根價格保護。')
 else:
  summary='以曆日末期貨收盤相對現貨收盤的正逆價差決定長抱一口方向，相反訊號直接反手。'
  ex+=['沒有固定停損、停利或最後一筆強平；資料最末根也不做新的跨日訊號，可能保留未平倉。']
  ca.append('換倉當根若同時為日界，平完可立即再按價差進場；這不是平舊後必然重開同方向。')
 add(name,summary,'價差與配對',entry,ex,[cost,'未使用KBAR間隔與共用開始／最後交易時間來篩報價；訊號按現貨日資料、內部成交按明確的close或open。'],ca,notes)
add('HD3','每天曆日末按期現價差新增一口獨立方向，持倉各自以OHLC停損／停利，容許多日多項重疊。','價差與配對',['每逢下一筆跨曆日，期貨close<查得現貨日收盤則多，否則空；同日可用現貨不存在時回退前日。','方向用該根close判，但新倉、固定停損／直停／啟移參考全部用同根open記錄；先處理舊倉與換倉，再新增該日一口。'],['僅通過ValidKBAR的根查風控。尚無移停時，多單只用open<=固定損退出，空單卻用high>=固定損並取max(open,線價)退出。','已存在移停時，先直停再回撤：多用high到直停與low到移停，空反向，各取有利／不利跳空open或線價。直停未啟移停前不生效。','更新移停用當根high/low判啟動，但新啟移與新線改從open換算；若同根close越新線立即按新線價退出。資料末筆以close退出全部啟動倉。'],[cost,'每個子項策略ID都設1，不是獨立帳本，反向同時倉會在共用FIFO先互抵。固定價位%以建立當根open計，移停更新%以每根open計。','換倉事件在舊倉一般保護後平舊開新、偏移保護參考；共用換倉函式一次一口，符合此版每子項一口。'],['close決定方向卻按同根open成交，訊號時刻與價位有先後偏差，不能視為收盤才成交。','移停新線只判不同就更新，沒有要求只能向有利方向推；多單固定損只看open而空側看high，兩側不對稱。','紀錄內多個同ID子項的獲利與全體FIFO可能不同，完整績效應以實際配對範圍判讀。'],{'KBAR間隔ex':'持倉風控依從開始交易時間起算的分鐘相位過濾；日界新進與末筆平倉不受此過濾。','開始交易時間':'KBAR分鐘相位原點，不另外禁止此前進場；日界另按曆日判。','停損比':'各新倉以訊號根open加減%或點數設固定損；多僅看後續open，空看high。','啟動移停比':'各新倉以open加減距離為初始啟移價；觸發後每次將啟移價改當根open。','移停拉回比':'每次更新以當根open換%或點數，重新加減成移停線；只要求不同，沒有單向鎖線。','直接停利比':'各新倉以open加減距離設直停，但只有已存在移停線時才檢查。'})
for name,up in [('大漲追夜盤',True),('大跌追夜盤',False)]:
 param='大漲點數' if up else '大跌點數';side='多' if up else '空';sign='加' if up else '減'
 add(name,'日盤指定時刻較開盤'+('上漲' if up else '下跌')+'達門檻，模擬從該時刻順勢做'+side+'到夜盤指定時間平倉。','日夜時段動量',['每個TradeDate的第一筆open記當日基準；日內合約delta只調此基準。指定收盤HHmm精確相等時，保存該根open為收盤參考。','直到夜盤出場HHmm精確相等才一次建兩筆紀錄：若保存價格'+('>=' if up else '<=')+'當日基準'+sign+'距離，回填收盤時間以保存價'+('買' if up else '賣')+'一口。'],['同一計算步驟立即以夜盤出場那根open平倉，不存在中途停損、停利或逐根持倉管理。'],[cost,'交易日以商品跨午夜規則判斷，日界第一筆只初始化就continue；名稱雖稱收盤，實際保存當根open，沒有使用完整close。'],['缺任何指定分鐘就不做該次交易，不會>=補價；若指定分鐘恰為日界第一筆，也因continue略過。','進場時間戳用出場日曆日加收盤時分回填；若夜盤出場設在跨午夜後，可把入場時間寫到平倉之後，不能當成已處理正確的隔日時間線。','程式Description提到N日跌幅與持有數天，但核心實際只看本交易日基準到指定收盤時刻，不採該段文字推測。'],{param:'本交易日首open的%或純點數門檻；保存收盤open'+('>=基準+距離' if up else '<=基準−距離')+'時才順勢交易。','收盤時間':'HHmm必須精確出現，保存當根open作入場價；真正紀錄在出場那根才回填。','夜盤出場時間':'HHmm精確出現時檢查門檻並以當根open完成平倉；缺值不補。'})
p.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Wrote 5 SuperDaily explanations')
